import{_ as o,c as r,o as t,a3 as s}from"./chunks/framework.Dokpd4od.js";const c=JSON.parse('{"title":"Orders to upsell","description":"","frontmatter":{},"headers":[],"relativePath":"master/sales/sales/invoicing/order-to-upsell.md","filePath":"master/sales/sales/invoicing/order-to-upsell.md","lastUpdated":1791902625000}'),a={name:"master/sales/sales/invoicing/order-to-upsell.md"};function n(i,e,l,d,h,p){return t(),r("div",null,e[0]||(e[0]=[s('<h1 id="orders-to-upsell" tabindex="-1">Orders to upsell <a class="header-anchor" href="#orders-to-upsell" aria-label="Permalink to &quot;Orders to upsell&quot;">​</a></h1><p>The <strong>Orders To Upsell</strong> page lists orders whose invoice status is <strong>Up Selling</strong>. These are orders where the delivered quantity is higher than the ordered quantity. Use the page to find orders that you may want to invoice for extra goods.</p><blockquote><p><strong>In simple words:</strong> This page shows orders where you delivered more than the customer ordered.</p></blockquote><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>Go to <code>Sales → To Invoice → Orders To Upsell</code>.</p><p>The page has the same views, columns and filters as <a href="./order-to-invoice.html">Orders to invoice</a>:</p><ul><li><strong>Default</strong>, <strong>My Orders</strong> and <strong>Archived</strong> views.</li><li><strong>Number</strong>, <strong>Creation Date</strong>, <strong>Customer</strong>, <strong>Sales Person</strong>, <strong>Amount Total</strong> and <strong>Status</strong> columns.</li></ul><p>When no order qualifies, the page shows <strong>No Orders To Upsells</strong>.</p><h2 id="when-an-order-appears-here" tabindex="-1">When an order appears here <a class="header-anchor" href="#when-an-order-appears-here" aria-label="Permalink to &quot;When an order appears here&quot;">​</a></h2><p>An order is listed when its invoice status becomes <strong>Up Selling</strong>. The app sets this status when:</p><ul><li>The order line uses the <strong>Ordered Quantities</strong> policy.</li><li>The delivered quantity is higher than the ordered quantity.</li></ul><p>For example, a customer orders 2 units and you deliver 3.</p><h2 id="what-to-do-next" tabindex="-1">What to do next <a class="header-anchor" href="#what-to-do-next" aria-label="Permalink to &quot;What to do next&quot;">​</a></h2><ol><li>Click the order to open it.</li><li>Check the <strong>Quantity</strong>, <strong>Delivered</strong> and <strong>Invoiced</strong> columns on the lines.</li><li>Decide how to handle the extra quantity with your customer.</li></ol><div class="info custom-block"><p class="custom-block-title">INFO</p><p>You can also see these orders on the <strong>Orders</strong> page of the Sales menu. See <a href="./../quotations-orders/manage-orders.html">Manage orders</a>.</p></div><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./invoicing-policies.html">Invoicing policies</a></li><li><a href="./order-to-invoice.html">Orders to invoice</a></li></ul>',17)]))}const g=o(a,[["render",n]]);export{c as __pageData,g as default};
